package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

const versionString = "zip-password-finder 0.10.3"
const aboutString = "Find the password of protected ZIP files"
const progName = "executable"

// Arguments holds parsed CLI arguments
type Arguments struct {
	InputFile          string
	Workers            *uint64
	PasswordDictionary *string
	Charset            string
	CharsetFile        *string
	MinPasswordLen     uint64
	MaxPasswordLen     uint64
	FileNumber         uint64
	StartingPassword   *string
}

// Option definition for help and parsing
type OptDef struct {
	Short       string // e.g. "-i" or ""
	Long        string // e.g. "--inputFile"
	ValueName   string // e.g. "<inputFile>"
	Help        string
	Default     string // default display value (without [default: ...])
	HasValue    bool
	IsHelp      bool
	IsVersion   bool
}

var optDefs = []OptDef{
	{Short: "-i", Long: "--inputFile", ValueName: "<inputFile>", Help: "path to zip input file", HasValue: true},
	{Short: "-w", Long: "--workers", ValueName: "<workers>", Help: "number of workers", HasValue: true},
	{Short: "-p", Long: "--passwordDictionary", ValueName: "<passwordDictionary>", Help: "path to a password dictionary file", HasValue: true},
	{Short: "-c", Long: "--charset", ValueName: "<charset>", Help: "charset to use to generate password", Default: "lud", HasValue: true},
	{Short: "", Long: "--charsetFile", ValueName: "<charsetFile>", Help: "path to a charset file", HasValue: true},
	{Short: "", Long: "--minPasswordLen", ValueName: "<minPasswordLen>", Help: "minimum password length", Default: "1", HasValue: true},
	{Short: "", Long: "--maxPasswordLen", ValueName: "<maxPasswordLen>", Help: "maximum password length", Default: "10", HasValue: true},
	{Short: "", Long: "--fileNumber", ValueName: "<fileNumber>", Help: "file number in the zip archive", Default: "0", HasValue: true},
	{Short: "-s", Long: "--startingPassword", ValueName: "<startingPassword>", Help: "password to start from", HasValue: true},
	{Short: "-h", Long: "--help", ValueName: "", Help: "Print help", IsHelp: true},
	{Short: "-V", Long: "--version", ValueName: "", Help: "Print version", IsVersion: true},
}

func formatOptionLabel(o OptDef) string {
	// "  -i, --inputFile <inputFile>"
	// If no short: "      --charsetFile <charsetFile>"
	var b strings.Builder
	b.WriteString("  ")
	if o.Short != "" {
		b.WriteString(o.Short)
		b.WriteString(", ")
	} else {
		b.WriteString("    ")
	}
	b.WriteString(o.Long)
	if o.ValueName != "" {
		b.WriteString(" ")
		b.WriteString(o.ValueName)
	}
	return b.String()
}

func printHelp() {
	fmt.Println(aboutString)
	fmt.Println()
	fmt.Printf("Usage: %s [OPTIONS] --inputFile <inputFile>\n", progName)
	fmt.Println()
	fmt.Println("Options:")
	// Calculate max label width
	labels := make([]string, len(optDefs))
	maxw := 0
	for i, o := range optDefs {
		labels[i] = formatOptionLabel(o)
		if len(labels[i]) > maxw {
			maxw = len(labels[i])
		}
	}
	// Clap pads labels to align help; use 2 spaces between label and help
	for i, o := range optDefs {
		help := o.Help
		if o.Default != "" {
			help = help + " [default: " + o.Default + "]"
		}
		padding := maxw - len(labels[i])
		fmt.Printf("%s%s  %s\n", labels[i], strings.Repeat(" ", padding), help)
	}
}

func printVersion() {
	fmt.Println(versionString)
}

// clapError prints to stderr and exits with code 2
func clapError(msg string, usageFull bool) {
	fmt.Fprintln(os.Stderr, "error: "+msg)
	fmt.Fprintln(os.Stderr)
	if usageFull {
		fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] --inputFile <inputFile>\n", progName)
	} else {
		fmt.Fprintf(os.Stderr, "Usage: %s --inputFile <inputFile>\n", progName)
	}
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

// clapErrorNoUsage prints to stderr, no usage line, and exits with code 2
func clapErrorNoUsage(msg string) {
	fmt.Fprintln(os.Stderr, "error: "+msg)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func findOptByLong(long string) *OptDef {
	for i, o := range optDefs {
		if o.Long == long {
			return &optDefs[i]
		}
	}
	return nil
}

func findOptByShort(short string) *OptDef {
	for i, o := range optDefs {
		if o.Short == short && o.Short != "" {
			return &optDefs[i]
		}
	}
	return nil
}

func parseArgs(argv []string) Arguments {
	args := Arguments{
		Charset:        "lud",
		MinPasswordLen: 1,
		MaxPasswordLen: 10,
		FileNumber:     0,
	}

	seen := map[string]bool{}

	setValue := func(opt *OptDef, value string) {
		if seen[opt.Long] {
			clapError("the argument '"+opt.Long+" "+opt.ValueName+"' cannot be used multiple times", true)
		}
		seen[opt.Long] = true
		switch opt.Long {
		case "--inputFile":
			args.InputFile = value
		case "--workers":
			v, err := parseUint(value, "--workers <workers>")
			if err != nil {
				clapErrorNoUsage(err.Error())
			}
			args.Workers = &v
		case "--passwordDictionary":
			args.PasswordDictionary = &value
		case "--charset":
			args.Charset = value
		case "--charsetFile":
			args.CharsetFile = &value
		case "--minPasswordLen":
			v, err := parseUint(value, "--minPasswordLen <minPasswordLen>")
			if err != nil {
				clapErrorNoUsage(err.Error())
			}
			args.MinPasswordLen = v
		case "--maxPasswordLen":
			v, err := parseUint(value, "--maxPasswordLen <maxPasswordLen>")
			if err != nil {
				clapErrorNoUsage(err.Error())
			}
			args.MaxPasswordLen = v
		case "--fileNumber":
			v, err := parseUint(value, "--fileNumber <fileNumber>")
			if err != nil {
				clapErrorNoUsage(err.Error())
			}
			args.FileNumber = v
		case "--startingPassword":
			args.StartingPassword = &value
		}
	}

	i := 0
	for i < len(argv) {
		a := argv[i]
		if a == "--" {
			// rest are positional - but this program has no positionals
			i++
			for ; i < len(argv); i++ {
				clapError("unexpected argument '"+argv[i]+"' found", true)
			}
			break
		}
		if strings.HasPrefix(a, "--") {
			// long option
			key := a
			var value string
			hasValue := false
			if idx := strings.Index(a, "="); idx >= 0 {
				key = a[:idx]
				value = a[idx+1:]
				hasValue = true
			}
			opt := findOptByLong(key)
			if opt == nil {
				// check for tip
				tip := suggestLong(key)
				var msg string
				if tip != "" {
					msg = "unexpected argument '" + key + "' found\n\n  tip: a similar argument exists: '" + tip + "'"
					// special usage line without [OPTIONS]
					fmt.Fprintln(os.Stderr, "error: "+msg)
					fmt.Fprintln(os.Stderr)
					// Usage: executable --inputFile <inputFile> [+ tip arg if the tip is not --inputFile itself]
					if tip == "--inputFile" {
						fmt.Fprintf(os.Stderr, "Usage: %s --inputFile <inputFile>\n", progName)
					} else {
						fmt.Fprintf(os.Stderr, "Usage: %s --inputFile <inputFile> %s\n", progName, tip)
					}
					fmt.Fprintln(os.Stderr)
					fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
					os.Exit(2)
				} else {
					clapError("unexpected argument '"+a+"' found", true)
				}
			}
			if opt.IsHelp {
				printHelp()
				os.Exit(0)
			}
			if opt.IsVersion {
				printVersion()
				os.Exit(0)
			}
			if opt.HasValue {
				if !hasValue {
					if i+1 >= len(argv) {
						clapErrorNoUsage("a value is required for '" + opt.Long + " " + opt.ValueName + "' but none was supplied")
					}
					i++
					value = argv[i]
				}
				setValue(opt, value)
			}
		} else if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short option
			rest := a[1:]
			for len(rest) > 0 {
				short := "-" + string(rest[0])
				rest = rest[1:]
				opt := findOptByShort(short)
				if opt == nil {
					clapError("unexpected argument '"+a+"' found", true)
				}
				if opt.IsHelp {
					printHelp()
					os.Exit(0)
				}
				if opt.IsVersion {
					printVersion()
					os.Exit(0)
				}
				if opt.HasValue {
					var value string
					if len(rest) > 0 {
						if rest[0] == '=' {
							value = rest[1:]
						} else {
							value = rest
						}
						rest = ""
					} else {
						if i+1 >= len(argv) {
							clapErrorNoUsage("a value is required for '" + opt.Long + " " + opt.ValueName + "' but none was supplied")
						}
						i++
						value = argv[i]
					}
					setValue(opt, value)
				}
			}
		} else {
			clapError("unexpected argument '"+a+"' found", true)
		}
		i++
	}

	if !seen["--inputFile"] {
		fmt.Fprintln(os.Stderr, "error: the following required arguments were not provided:")
		fmt.Fprintln(os.Stderr, "  --inputFile <inputFile>")
		fmt.Fprintln(os.Stderr)
		fmt.Fprintf(os.Stderr, "Usage: %s --inputFile <inputFile>\n", progName)
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
		os.Exit(2)
	}
	return args
}

func parseUint(s string, argDesc string) (uint64, error) {
	// clap 4 parses via FromStr for u64, errors are:
	// - "invalid digit found in string"
	// - "number too large to fit in target type"
	// - "cannot parse integer from empty string"
	if s == "" {
		return 0, fmt.Errorf("invalid value '%s' for '%s': cannot parse integer from empty string", s, argDesc)
	}
	// check negative/leading '-' or '+' (Rust u64::from_str rejects '+' and '-')
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		if numErr, ok := err.(*strconv.NumError); ok {
			switch numErr.Err {
			case strconv.ErrRange:
				return 0, fmt.Errorf("invalid value '%s' for '%s': number too large to fit in target type", s, argDesc)
			default:
				return 0, fmt.Errorf("invalid value '%s' for '%s': invalid digit found in string", s, argDesc)
			}
		}
		return 0, fmt.Errorf("invalid value '%s' for '%s': invalid digit found in string", s, argDesc)
	}
	return v, nil
}

// suggestLong finds a similar long option name, if any
func suggestLong(input string) string {
	// Use a simple case-insensitive prefix match or Levenshtein-like distance
	// Clap uses strsim with a threshold. Simple heuristic:
	input = strings.TrimPrefix(input, "--")
	candidates := []string{}
	for _, o := range optDefs {
		if o.Long != "" {
			candidates = append(candidates, strings.TrimPrefix(o.Long, "--"))
		}
	}
	best := ""
	bestScore := 0.0
	for _, c := range candidates {
		s := similarity(input, c)
		if s > bestScore {
			bestScore = s
			best = c
		}
	}
	if bestScore >= 0.7 {
		return "--" + best
	}
	return ""
}

// similarity: Jaro-Winkler-like approximation (simple)
func similarity(a, b string) float64 {
	la := strings.ToLower(a)
	lb := strings.ToLower(b)
	if la == lb {
		return 1.0
	}
	// case-insensitive prefix match
	if strings.HasPrefix(lb, la) || strings.HasPrefix(la, lb) {
		// good match
		minLen := len(la)
		if len(lb) < minLen {
			minLen = len(lb)
		}
		maxLen := len(la)
		if len(lb) > maxLen {
			maxLen = len(lb)
		}
		return float64(minLen) / float64(maxLen)
	}
	return 0
}

// CliError - runtime error
func cliError(msg string) {
	fmt.Println("CLI argument error - " + strconv.Quote(msg))
	os.Exit(1)
}

// main
func main() {
	args := parseArgs(os.Args[1:])
	start := time.Now()
	_ = start
	run(args)
}

func run(args Arguments) {
	// Validation order:
	// 1. inputFile exists
	if !fileExists(args.InputFile) {
		cliError("'inputFile' does not exist")
	}
	// 2. passwordDictionary exists (if given)
	if args.PasswordDictionary != nil {
		if !fileExists(*args.PasswordDictionary) {
			cliError("'passwordDictionary' does not exist")
		}
	}
	// 3. charsetFile exists (if given)
	if args.CharsetFile != nil {
		if !fileExists(*args.CharsetFile) {
			cliError("'charsetFile' does not exist")
		}
	}
	// 4. workers > 0
	if args.Workers != nil && *args.Workers == 0 {
		cliError("'workers' must be positive")
	}
	// 5. minPasswordLen > 0
	if args.MinPasswordLen == 0 {
		cliError("'minPasswordLen' must be positive")
	}
	// 6. maxPasswordLen > 0
	if args.MaxPasswordLen == 0 {
		cliError("'maxPasswordLen' must be positive")
	}
	// 7. maxPasswordLen >= minPasswordLen
	if args.MaxPasswordLen < args.MinPasswordLen {
		cliError("'maxPasswordLen' must be equal or greater than 'minPasswordLen'")
	}
	// 8. charset validity (build it)
	var charset []byte
	if args.PasswordDictionary == nil {
		if args.CharsetFile != nil {
			data, err := os.ReadFile(*args.CharsetFile)
			if err != nil {
				cliError("'charsetFile' does not exist")
			}
			// remove newline chars
			s := strings.ReplaceAll(strings.ReplaceAll(string(data), "\r", ""), "\n", "")
			charset = dedup([]byte(s))
			sort.Slice(charset, func(i, j int) bool { return charset[i] < charset[j] })
		} else {
			cs, err := charsetFromOption(args.Charset)
			if err != nil {
				cliError(err.Error())
			}
			charset = cs
		}
	}
	// 9. startingPassword + dictionary
	if args.StartingPassword != nil {
		if args.PasswordDictionary != nil {
			cliError("'startingPassword' cannot be used with a dictionary file")
		}
		sp := *args.StartingPassword
		if uint64(len(sp)) < args.MinPasswordLen || uint64(len(sp)) > args.MaxPasswordLen {
			cliError("'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration")
		}
		for _, c := range []byte(sp) {
			if !containsByte(charset, c) {
				cliError("'startingPassword' uses characters out of the generation charset")
			}
		}
	}

	// Open zip and find the encrypted file
	zf, err := openZip(args.InputFile)
	if err != nil {
		fmt.Printf("Invalid zip file error - %s\n", err.Error())
		os.Exit(1)
	}
	if args.FileNumber >= uint64(len(zf.Files)) {
		fmt.Printf("File number not found within archive error - '%d'\n", args.FileNumber)
		os.Exit(1)
	}
	target := zf.Files[args.FileNumber]
	if !target.Encrypted {
		fmt.Printf("Invalid zip file error - the selected file in the archive is not encrypted (file_number:%d file_name:%s)\n", args.FileNumber, target.Name)
		os.Exit(1)
	}

	// Run the search
	start := time.Now()
	found := ""
	if args.PasswordDictionary != nil {
		found = dictionaryAttack(*args.PasswordDictionary, target)
	} else {
		startingPass := ""
		if args.StartingPassword != nil {
			startingPass = *args.StartingPassword
		}
		found = bruteForceAttack(charset, args.MinPasswordLen, args.MaxPasswordLen, startingPass, target)
	}

	elapsed := time.Since(start)
	fmt.Println("Time elapsed: " + formatDuration(elapsed))
	if found != "" {
		fmt.Println("Password found:" + found)
	} else {
		fmt.Println("Password not found")
	}
}

func fileExists(path string) bool {
	st, err := os.Stat(path)
	if err != nil {
		return false
	}
	_ = st
	return true
}

func containsByte(arr []byte, b byte) bool {
	for _, x := range arr {
		if x == b {
			return true
		}
	}
	return false
}

func dedup(arr []byte) []byte {
	seen := map[byte]bool{}
	out := []byte{}
	for _, b := range arr {
		if !seen[b] {
			seen[b] = true
			out = append(out, b)
		}
	}
	return out
}

func charsetFromOption(opt string) ([]byte, error) {
	var chars []byte
	for i := 0; i < len(opt); i++ {
		c := opt[i]
		switch c {
		case 'l':
			chars = append(chars, []byte("abcdefghijklmnopqrstuvwxyz")...)
		case 'u':
			chars = append(chars, []byte("ABCDEFGHIJKLMNOPQRSTUVWXYZ")...)
		case 'd':
			chars = append(chars, []byte("0123456789")...)
		case 'h':
			chars = append(chars, []byte("0123456789abcdef")...)
		case 'H':
			chars = append(chars, []byte("0123456789ABCDEF")...)
		case 's':
			chars = append(chars, []byte(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")...)
		default:
			return nil, fmt.Errorf("Unknown charset option '%c'", c)
		}
	}
	chars = dedup(chars)
	sort.Slice(chars, func(i, j int) bool { return chars[i] < chars[j] })
	return chars, nil
}

func formatDuration(d time.Duration) string {
	ns := d.Nanoseconds()
	if ns <= 0 {
		return "0s"
	}
	s := ns / 1_000_000_000
	ns = ns % 1_000_000_000
	ms := ns / 1_000_000
	ns = ns % 1_000_000
	us := ns / 1_000
	ns = ns % 1_000

	parts := []string{}
	if s > 0 {
		parts = append(parts, fmt.Sprintf("%ds", s))
	}
	if ms > 0 {
		parts = append(parts, fmt.Sprintf("%dms", ms))
	}
	if us > 0 {
		parts = append(parts, fmt.Sprintf("%dus", us))
	}
	if ns > 0 {
		parts = append(parts, fmt.Sprintf("%dns", ns))
	}
	if len(parts) == 0 {
		return "0s"
	}
	return strings.Join(parts, " ")
}
