	for i := len(buf) - 22; i >= 0; i-- {
		if buf[i] == 0x50 && buf[i+1] == 0x4b && buf[i+2] == 0x05 && buf[i+3] == 0x06 {
			eocdOffset = int64(i)
			break
		}
	}
	if eocdOffset == -1 {
		return nil, fmt.Errorf("invalid zip: EOCD not found")
