	// 10: total entries, 12: CD size, 16: CD offset, 20: comment len
	totalEntries := binary.LittleEndian.Uint16(eocd[10:12])
	cdSize := binary.LittleEndian.Uint32(eocd[12:16])
	cdOffset := binary.LittleEndian.Uint32(eocd[16:20])

