		method := binary.LittleEndian.Uint16(cdBuf[p+10 : p+12])
		modTime := binary.LittleEndian.Uint16(cdBuf[p+12 : p+14])
		modDate := binary.LittleEndian.Uint16(cdBuf[p+14 : p+16])
		crc := binary.LittleEndian.Uint32(cdBuf[p+16 : p+20])
		compSize := binary.LittleEndian.Uint32(cdBuf[p+20 : p+24])
		uncompSize := binary.LittleEndian.Uint32(cdBuf[p+24 : p+28])
