// readLocalDataOffset opens the file and reads the local file header to compute the data offset
func readLocalDataOffset(path string, e *ZipFileEntry) (int64, error) {
	f, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	defer f.Close()
	hdr := make([]byte, 30)
	if _, err := f.ReadAt(hdr, int64(e.LocalHeaderOffset)); err != nil {
		return 0, err
	}
	sig := binary.LittleEndian.Uint32(hdr[0:4])
	if sig != 0x04034b50 {
		return 0, fmt.Errorf("invalid local file header signature")
	}
	nameLen := binary.LittleEndian.Uint16(hdr[26:28])
	extraLen := binary.LittleEndian.Uint16(hdr[28:30])
	return int64(e.LocalHeaderOffset) + 30 + int64(nameLen) + int64(extraLen), nil
}

// readEncryptedData reads the encrypted bytes (from data offset onward) up to compressed size
func readEncryptedData(path string, e *ZipFileEntry) ([]byte, error) {
	off, err := readLocalDataOffset(path, e)
	if err != nil {
		return nil, err
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	buf := make([]byte, e.CompressedSize)
	_, err = f.ReadAt(buf, off)
	if err != nil && err != io.EOF {
		return nil, err
	}
	return buf, nil
}
