package main

import (
	"crypto/aes"
	"crypto/hmac"
	"crypto/sha1"
	"hash"
)

// PBKDF2-HMAC-SHA1
func pbkdf2HmacSHA1(password, salt []byte, iterations int, keyLen int) []byte {
	prf := hmac.New(sha1.New, password)
	hLen := prf.Size()
	l := (keyLen + hLen - 1) / hLen
	result := make([]byte, 0, l*hLen)
	buf := make([]byte, hLen)
	u := make([]byte, hLen)
	for i := 1; i <= l; i++ {
		prf.Reset()
		prf.Write(salt)
		prf.Write([]byte{byte(i >> 24), byte(i >> 16), byte(i >> 8), byte(i)})
		u = prf.Sum(u[:0])
		copy(buf, u)
		for j := 2; j <= iterations; j++ {
			prf.Reset()
			prf.Write(u)
			u = prf.Sum(u[:0])
			for k := range buf {
				buf[k] ^= u[k]
			}
		}
		result = append(result, buf...)
	}
	return result[:keyLen]
}

// aesStrengthKeySize returns (keyLen, saltLen) for AES strength 1/2/3
func aesStrengthParams(strength byte) (keyLen int, saltLen int) {
	switch strength {
	case 1:
		return 16, 8
	case 2:
		return 24, 12
	case 3:
		return 32, 16
	}
	return 0, 0
}

// tryPasswordAES checks if password matches for AES-encrypted entry
// data = the raw encrypted data for this entry (salt + verification + ciphertext + mac)
// It returns true if the 2-byte password verification matches. It does NOT verify the HMAC.
func tryPasswordAES(password string, data []byte, strength byte) bool {
	keyLen, saltLen := aesStrengthParams(strength)
	if keyLen == 0 {
		return false
	}
	if len(data) < saltLen+2 {
		return false
	}
	salt := data[:saltLen]
	verif := data[saltLen : saltLen+2]
	derived := pbkdf2HmacSHA1([]byte(password), salt, 1000, 2*keyLen+2)
	pv := derived[2*keyLen:]
	return pv[0] == verif[0] && pv[1] == verif[1]
}

// tryPasswordAESFull does the verification AND the HMAC check (more accurate)
func tryPasswordAESFull(password string, data []byte, strength byte) bool {
	keyLen, saltLen := aesStrengthParams(strength)
	if keyLen == 0 {
		return false
	}
	if len(data) < saltLen+2+10 {
		return false
	}
	salt := data[:saltLen]
	verif := data[saltLen : saltLen+2]
	cipherEnd := len(data) - 10
	cipherText := data[saltLen+2 : cipherEnd]
	mac := data[cipherEnd:]
	derived := pbkdf2HmacSHA1([]byte(password), salt, 1000, 2*keyLen+2)
	encKey := derived[:keyLen]
	hmacKey := derived[keyLen : 2*keyLen]
	pv := derived[2*keyLen:]
	if pv[0] != verif[0] || pv[1] != verif[1] {
		return false
	}
	mh := hmac.New(sha1.New, hmacKey)
	mh.Write(cipherText)
	got := mh.Sum(nil)[:10]
	for i := 0; i < 10; i++ {
		if got[i] != mac[i] {
			return false
		}
	}
	_ = encKey
	return true
}

