type zipcryptoKeys struct {
	k0, k1, k2 uint32
}

var crcTable [256]uint32

func init() {
	for i := 0; i < 256; i++ {
		c := uint32(i)
		for j := 0; j < 8; j++ {
			if c&1 != 0 {
				c = (c >> 1) ^ 0xEDB88320
			} else {
				c >>= 1
			}
		}
		crcTable[i] = c
	}
}

func crc32Update(prev uint32, b byte) uint32 {
	return (prev >> 8) ^ crcTable[(prev^uint32(b))&0xFF]
}

func (k *zipcryptoKeys) init(password string) {
	k.k0 = 0x12345678
	k.k1 = 0x23456789
	k.k2 = 0x34567890
	for i := 0; i < len(password); i++ {
