	k.k0 = crc32Update(k.k0, b)
	k.k1 = k.k1 + (k.k0 & 0xFF)
	k.k1 = k.k1*134775813 + 1
	k.k2 = crc32Update(k.k2, byte(k.k1>>24))
}

func (k *zipcryptoKeys) stream() byte {
	temp := (k.k2 | 2) & 0xFFFF
	return byte(((temp * (temp ^ 1)) >> 8) & 0xFF)
}

func (k *zipcryptoKeys) decryptByte(c byte) byte {
	s := k.stream()
	p := c ^ s
	k.updateKeys(p)
	return p
}

