	for i := 0; i < 12; i++ {
		last = keys.decryptByte(encryptedHeader[i])
	}
	var expected byte
	if e.FlagBits&0x08 != 0 {
		// use high byte of mod time
		expected = byte(e.LastModTime >> 8)
	} else {
		expected = byte(e.CRC32 >> 24)
	}
	return last == expected
}

