	"runtime"
	"strings"
	"sync"
	"sync/atomic"
)

type tester struct {
	entry *ZipFileEntry
	data  []byte // encrypted data
}

func newTester(path string, e *ZipFileEntry) (*tester, error) {
	data, err := readEncryptedData(path, e)
	if err != nil {
		return nil, err
	}
	return &tester{entry: e, data: data}, nil
}

func (t *tester) try(password string) bool {
	if t.entry.IsAES {
		// First try only the fast password verification check.
		// If it passes, do full HMAC verification to avoid false positives.
		if !tryPasswordAES(password, t.data, t.entry.AESStrength) {
			return false
		}
		return tryPasswordAESFull(password, t.data, t.entry.AESStrength)
	}
	return tryPasswordZipCrypto(password, t.data, t.entry)
}

func workerCount() int {
	n := runtime.NumCPU()
	if n < 1 {
		n = 1
	}
	return n
}

// dictionaryAttack reads passwords from dict file line-by-line
func dictionaryAttack(dictPath string, entry *ZipFileEntry) string {
	nWorkers := workerCount()
	t, err := newTester(getZipPath(), entry)
	if err != nil {
		return ""
	}

	ch := make(chan string, 1024)
	var found atomic.Value
	found.Store("")
	var stopped atomic.Bool
	var wg sync.WaitGroup

	for i := 0; i < nWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for pw := range ch {
				if stopped.Load() {
					continue
				}
				if t.try(pw) {
					if !stopped.Swap(true) {
						found.Store(pw)
					}
					return
				}
			}
		}()
	}

	f, err := os.Open(dictPath)
	if err != nil {
		close(ch)
		wg.Wait()
		return ""
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024), 10*1024*1024)
	for scanner.Scan() {
		if stopped.Load() {
			break
		}
		line := scanner.Text()
		// Rust's lines() strips \n and trailing \r
		line = strings.TrimSuffix(line, "\r")
		ch <- line
	}
	close(ch)
	wg.Wait()
	return found.Load().(string)
}

// zipPath is set during run() for passing around
var zipPath string

func getZipPath() string { return zipPath }
func setZipPath(p string) { zipPath = p }

// bruteForceAttack iterates through all passwords in charset order
func bruteForceAttack(charset []byte, minLen, maxLen uint64, startingPass string, entry *ZipFileEntry) string {
	nWorkers := workerCount()
	t, err := newTester(getZipPath(), entry)
	if err != nil {
