			for pw := range ch {
				if stopped.Load() {
					continue
				}
				if t.try(pw) {
					if !stopped.Swap(true) {
						found.Store(pw)
					}
					return
				}
			}
		}()
	}

	startingIdx := indexInCharset(charset, startingPass)
	for L := minLen; L <= maxLen; L++ {
		if stopped.Load() {
			break
		}
		// Determine start index for this length
		var startIdx []int
		if startingPass != "" && uint64(len(startingPass)) == L {
			startIdx = startingIdx
		}
		if startIdx == nil {
			startIdx = make([]int, L)
		}
		idx := make([]int, L)
		copy(idx, startIdx)
		// iterate
		for {
			if stopped.Load() {
				break
			}
			// build password
