			for i := range idx {
				pw[i] = charset[idx[i]]
			}
			ch <- string(pw)
			// increment
			i := int(L) - 1
			for i >= 0 {
				idx[i]++
				if idx[i] < len(charset) {
					break
				}
				idx[i] = 0
				i--
			}
			if i < 0 {
				break
			}
		}
		// startingPass only applies to its own length; subsequent lengths start at 0
		startingPass = ""
	}
	close(ch)
	wg.Wait()
	return found.Load().(string)
}

// indexInCharset returns the indices of each byte of pw in charset
func indexInCharset(charset []byte, pw string) []int {
	if pw == "" {
		return nil
	}
	idx := make([]int, len(pw))
	for i := 0; i < len(pw); i++ {
		for j, c := range charset {
			if c == pw[i] {
				idx[i] = j
				break
			}
		}
	}
	return idx
}
