		body[i] = keys.decryptByte(data[12+i])
	}
	// decompress if needed
	var plain []byte
	switch e.CompressMethod {
	case 0:
		plain = body
	case 8:
		r := flate.NewReader(bytes.NewReader(body))
		var buf bytes.Buffer
		_, err := io.Copy(&buf, r)
