// indexFromDigits converts the mixed-radix representation to a linear index.
func indexFromDigits(digits []int, base int) uint64 {
	var idx uint64
	for _, d := range digits {
		idx = idx*uint64(base) + uint64(d)
	}
	return idx
}

// digitsFromIndex computes digits (most-significant-first) of idx in given base
// with the length of the output slice fixed.
func digitsFromIndex(digits []int, idx uint64, base int) {
	for i := len(digits) - 1; i >= 0; i-- {
		digits[i] = int(idx % uint64(base))
		idx /= uint64(base)
	}
}

// indexInCharset returns the indices of each byte of pw in charset
func indexInCharset(charset []byte, pw string) []int {
	if pw == "" {
		return nil
	}
	idx := make([]int, len(pw))
	for i := 0; i < len(pw); i++ {
		for j, c := range charset {
			if c == pw[i] {
				idx[i] = j
				break
			}
		}
	}
	return idx
}
